openFiles.content:
.SequencerApp {
  height: 100vh;
  display: flex;
  flex-direction: column;
  position: relative;
  background: #0b0f17;
  color: #e8eefc;
  color-scheme: dark;
  overflow: hidden;
}

.SequencerAppMain {
  flex: 1;
  display: flex;
  min-height: 0;
  min-width: 0;
  position: relative;
  overflow: hidden;
}

.SequencerSidebar {
  width: 300px;
  min-width: 300px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(0, 0, 0, 0.2);
  display: flex;
  flex-direction: column;
  min-height: 0;
  transition: width 0.3s ease, min-width 0.3s ease, flex-basis 0.3s ease;
}

.SequencerSidebar.isCollapsed {
  width: 56px;
  min-width: 56px;
  overflow: hidden;
}

.SequencerSidebar.isResizing {
  transition: none;
}

.SequencerPanelResizeHandle {
  flex: 0 0 12px;
  width: 12px;
  min-width: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: col-resize;
  user-select: none;
  touch-action: none;
  background: rgba(255, 255, 255, 0.01);
  border-left: 1px solid rgba(255, 255, 255, 0.04);
  border-right: 1px solid rgba(255, 255, 255, 0.04);
  transition: background 0.18s ease, box-shadow 0.18s ease;
}

.SequencerPanelResizeHandle:hover,
.SequencerPanelResizeHandle.isDragging {
  background: rgba(0, 255, 255, 0.08);
  box-shadow: inset 0 0 0 1px rgba(0, 255, 255, 0.18);
}

.SequencerPanelResizeGrip {
  width: 3px;
  height: 72px;
  max-height: calc(100% - 24px);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  box-shadow: 0 0 0 1px rgba(0, 255, 255, 0.06);
  transition: background 0.18s ease, box-shadow 0.18s ease;
}

.SequencerPanelResizeHandle:hover .SequencerPanelResizeGrip,
.SequencerPanelResizeHandle.isDragging .SequencerPanelResizeGrip {
  background: rgba(0, 255, 255, 0.72);
  box-shadow: 0 0 10px rgba(0, 255, 255, 0.28);
}

.SequencerMobileInspectorToggle {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 26;
  min-height: 36px;
  padding: 0 12px;
  border-radius: 999px;
  border: 1px solid rgba(0, 255, 255, 0.35);
  background: rgba(5, 12, 20, 0.88);
  color: #dffcff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(8px);
  cursor: pointer;
}

.SequencerMobileInspectorBackdrop {
  position: absolute;
  inset: 0;
  z-index: 27;
  border: 0;
  padding: 0;
  background: rgba(2, 8, 14, 0.42);
  backdrop-filter: blur(2px);
  cursor: pointer;
}

.SequencerSidebarTop {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.SequencerSidebar.isCollapsed .SequencerSidebarTop {
  padding: 10px 8px;
  justify-content: center;
}

.SequencerSidebarContent {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  opacity: 1;
  transform: translateX(0);
  transition: opacity 0.22s ease, transform 0.26s ease;
}

.SequencerSidebarContent.isCollapsed {
  opacity: 0;
  transform: translateX(-8px);
  pointer-events: none;
}

.SequencerSidebarHeader {
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: stretch;
}

.SequencerSidebarHeaderActions {
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: stretch;
}

.SequencerSidebarPrimaryActions {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: nowrap;
}

.SequencerSidebarPrimaryActions .SequencerSidebarPrimaryButton {
  flex: 1 1 0;
  min-width: 0;
}

.SequencerInlineConfirm {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  padding: 6px 8px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(0, 0, 0, 0.25);
}

.SequencerInlineConfirmText {
  font-size: 12px;
  opacity: 0.85;
  white-space: nowrap;
}

.SequencerSidebarHeaderRow {
  display: flex;
  gap: 8px;
  align-items: center;
}

.SequencerSidebarSubheader {
  padding: 8px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 12px;
  opacity: 0.85;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.SequencerSidebarFilters {
  padding: 6px 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  gap: 3px;
  flex-wrap: nowrap;
  align-items: center;
  background: rgba(255, 255, 255, 0.02);
  overflow: hidden;
}

.SequencerSidebarFilters .SequencerSmallButton {
  border-radius: 999px;
  padding: 5px 6px;
  font-size: 10px;
  letter-spacing: 0.06em;
  flex: 1 1 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: center;
}

.SequencerSidebarHeaderRow input {
  flex: 1;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #e8eefc;
  border-radius: 6px;
  padding: 8px 10px;
  outline: none;
}

.SequencerSidebarBody {
  flex: 1;
  overflow: auto;
  padding: 10px 12px;
  transition: opacity 0.22s ease, transform 0.26s ease;
}

.SequencerSectionTitle {
  font-size: 12px;
  letter-spacing: 0.08em;
  opacity: 0.8;
  margin: 10px 0 6px;
}

.SequencerSectionToggle {
  width: 100%;
  margin: 10px 0 6px;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  cursor: pointer;
  text-align: left;
}

.SequencerSectionToggleMain {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  cursor: pointer;
  text-align: left;
}

.SequencerSectionToggleLabel {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  letter-spacing: 0.08em;
  opacity: 0.86;
}

.SequencerSectionToggleCount {
  opacity: 0.72;
  letter-spacing: normal;
}

.SequencerSectionToggleIcon {
  font-size: 13px;
  opacity: 0.78;
}

.SequencerSectionToggle:hover .SequencerSectionToggleLabel,
.SequencerSectionToggleMain:hover .SequencerSectionToggleLabel {
  opacity: 1;
}

.SequencerSectionToggleWithActions {
  align-items: center;
}

.SequencerSectionToggleActions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.SequencerCurrentSequenceName {
  padding: 6px 2px 0;
  font-size: 14px;
  line-height: 1.2;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.92);
  white-space: normal;
  overflow: visible;
  text-overflow: unset;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.SequencerList {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.SequencerItemLeft {
  display: flex;
  gap: 10px;
  align-items: center;
  min-width: 0;
  flex: 1 1 180px;
}

.SequencerItemRight {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  row-gap: 4px;
  align-items: center;
  flex-shrink: 0;
}

.SequencerItemText {
  min-width: 0;
  flex: 1;
}

.SequencerThumb {
  width: 56px;
  height: 56px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  object-fit: cover;
  background: rgba(0, 0, 0, 0.25);
}

.SequencerBadge {
  font-size: 10px;
  letter-spacing: 0.08em;
  padding: 4px 6px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.06);
  white-space: nowrap;
  opacity: 0.9;
  flex-shrink: 0;
}

.SequencerBadgePreset {
  border-color: rgba(0, 255, 255, 0.45);
  color: rgba(0, 255, 255, 0.9);
}

.SequencerBadgeComposite {
  border-color: rgba(255, 119, 255, 0.5);
  color: rgba(255, 119, 255, 0.95);
}

.SequencerBadgeSeq {
  border-color: rgba(255, 200, 0, 0.55);
  color: rgba(255, 200, 0, 0.95);
}

.SequencerBadgeLayer {
  border-color: rgba(160, 120, 255, 0.55);
  color: rgba(160, 120, 255, 0.95);
}

.SequencerBadgeEffect {
  border-color: rgba(0, 255, 255, 0.45);
  color: rgba(0, 255, 255, 0.9);
}

.SequencerItem {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 8px;
  padding: 8px 10px;
  cursor: pointer;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  user-select: none;
}

.SequencerItemSeq {
  display: grid;
  grid-template-columns: 56px 1fr;
  grid-template-rows: auto auto;
  column-gap: 10px;
  row-gap: 6px;
  align-items: center;
}

.SequencerSeqThumb {
  grid-column: 1;
  grid-row: 1 / span 2;
}

.SequencerSeqHeader {
  grid-column: 2;
  grid-row: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.SequencerSeqName {
  min-width: 0;
  flex: 1;
  font-size: 13px;
  line-height: 1.2;
  overflow-x: auto;
  overflow-y: hidden;
  text-overflow: clip;
  white-space: nowrap;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.SequencerSeqName::-webkit-scrollbar {
  height: 0;
}

.SequencerSeqActions {
  grid-column: 2;
  grid-row: 2;
  display: flex;
  gap: 8px;
  align-items: center;
}

.SequencerSeqActionsSpacer {
  flex: 1;
}

.SequencerSeqIconButton {
  width: 34px;
  height: 30px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.SequencerItem:hover {
  border-color: rgba(0, 255, 255, 0.35);
}

.SequencerItem[draggable="true"] {
  cursor: grab;
}

.SequencerItem[draggable="true"]:active {
  cursor: grabbing;
}

.SequencerItemName {
  font-size: 13px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.SequencerItemMeta {
  font-size: 11px;
  opacity: 0.7;
}

.SequencerContent {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.SequencerTopBar {
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}

.SequencerTopBarActions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
}

.SequencerTopBar button {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #e8eefc;
  border-radius: 7px;
  padding: 8px 10px;
  cursor: pointer;
}

.SequencerTopBar button:hover {
  border-color: rgba(0, 255, 255, 0.35);
}

.SequencerIconButton {
  width: 36px;
  height: 36px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 15px;
  line-height: 1;
}

.SequencerIconButton.isOn {
  border-color: rgba(0, 255, 255, 0.55);
  background: rgba(0, 255, 255, 0.14);
}

.SequencerTransportButton {
  min-width: 74px;
  height: 34px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border-radius: 8px;
  background: #111;
  border-color: rgba(255, 255, 255, 0.18);
  font-size: 12px;
  letter-spacing: 0.06em;
}

.SequencerTransportButtonIcon {
  font-size: 13px;
  line-height: 1;
}

.SequencerTransportButtonLabel {
  line-height: 1;
}

.SequencerOutputMapButton {
  height: 36px;
  padding: 0 10px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  letter-spacing: 0.08em;
  line-height: 1;
}

.SequencerTagToggleButton {
  min-width: 92px;
  justify-content: center;
}

.SequencerOutputMapButton.isOn {
  border-color: rgba(0, 255, 255, 0.55);
  background: rgba(0, 255, 255, 0.14);
}

.SequencerOutputMapEye {
  font-size: 14px;
}

.SequencerOutputMapEye.isOff {
  opacity: 0.35;
}

.SequencerTopBarMeta {
  opacity: 0.85;
  font-size: 12px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.SequencerTopBarMetaCurrent {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-variant-numeric: tabular-nums;
}

.SequencerDurationInput {
  width: 140px;
  height: 30px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #e8eefc;
  border-radius: 7px;
  padding: 0 10px;
  outline: none;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  font-variant-numeric: tabular-nums;
}

.SequencerDurationInput:focus {
  border-color: rgba(0, 255, 255, 0.45);
  box-shadow: 0 0 0 2px rgba(0, 255, 255, 0.12);
}

.SequencerTopBarMetaStatus {
  margin-left: 10px;
  opacity: 0.75;
}

.SequencerTransportBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

.SequencerTransportBarLeft {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.SequencerTransportBarMeta {
  margin-left: 8px;
}

.SequencerCloseModalOverlay {
  position: fixed;
  inset: 0;
  z-index: 1000000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(3, 8, 18, 0.72);
  backdrop-filter: blur(6px);
}

.SequencerCloseModal {
  width: min(460px, calc(100vw - 32px));
  border-radius: 14px;
  border: 1px solid rgba(0, 255, 255, 0.24);
  background:
    linear-gradient(180deg, rgba(14, 21, 34, 0.98), rgba(7, 12, 22, 0.98));
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.48);
  overflow: hidden;
}

.SequencerCloseModalHeader {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.SequencerCloseModalTitle {
  color: #e8eefc;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.SequencerCloseModalBody {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.SequencerCloseModalMessage {
  font-size: 15px;
  color: rgba(232, 238, 252, 0.96);
}

.SequencerCloseModalDetail {
  font-size: 13px;
  line-height: 1.5;
  color: rgba(232, 238, 252, 0.76);
}

.SequencerCloseModalActions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 0 18px 18px;
}

.SequencerPreview {
  flex: 1;
  min-height: 0;
  position: relative;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: #000;
  transition: filter 0.25s ease, opacity 0.25s ease;
}

.SequencerStatsOverlay {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 6;
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
}

.SequencerStatsToggle {
  width: 34px;
  height: 34px;
  border-radius: 999px;
  border: 1px solid rgba(0, 255, 255, 0.32);
  background: rgba(5, 12, 20, 0.76);
  color: #8ffcff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  pointer-events: auto;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(8px);
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.SequencerStatsToggle:hover {
  background: rgba(8, 18, 28, 0.92);
  border-color: rgba(0, 255, 255, 0.55);
  transform: translateY(-1px);
}

.SequencerStatsToggle.isActive {
  background: rgba(0, 255, 255, 0.12);
  border-color: rgba(0, 255, 255, 0.72);
}

.SequencerStatsIconSvg {
  width: 16px;
  height: 16px;
}

.SequencerStatsPanel {
  width: 220px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid rgba(0, 255, 255, 0.22);
  background: rgba(2, 8, 14, 0.74);
  color: rgba(228, 249, 255, 0.96);
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 12px;
  line-height: 1.35;
  pointer-events: auto;
  backdrop-filter: blur(10px);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.32);
}

.SequencerStatsTitleRow,
.SequencerStatsMetricRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.SequencerStatsTitleRow {
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.SequencerStatsMetricRow + .SequencerStatsMetricRow {
  margin-top: 6px;
}

.SequencerStatsTitle {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #8ffcff;
}

.SequencerStatsSource,
.SequencerStatsLabel {
  color: rgba(188, 220, 228, 0.82);
}

.SequencerStatsSource {
  font-size: 10px;
  text-transform: uppercase;
}

.SequencerStatsValue {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: #ffffff;
}

.SequencerTimelineResizeHandle {
  height: 14px;
  flex: 0 0 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: row-resize;
  background: #000;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  user-select: none;
}

.SequencerTimelineResizeHandle:hover,
.SequencerTimelineResizeHandle.isDragging {
  background: rgba(255, 255, 255, 0.03);
}

.SequencerTimelineResizeGrip {
  width: 120px;
  max-width: calc(100% - 24px);
  height: 3px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  box-shadow: 0 0 0 1px rgba(0, 255, 255, 0.06);
}

.SequencerTimelineResizeHandle:hover .SequencerTimelineResizeGrip,
.SequencerTimelineResizeHandle.isDragging .SequencerTimelineResizeGrip {
  background: rgba(0, 255, 255, 0.65);
}

.SequencerTimeline {
  height: 280px;
  min-height: 220px;
  background: #000;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overscroll-behavior-x: contain;
  transition: height 0.26s ease;
}

.SequencerTimeline.isDraggingResize {
  transition: none;
}

.SequencerTimeBar {
  height: 48px;
  display: flex;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background: #000;
}

.SequencerTimeBarLeft {
  width: 220px;
  min-width: 220px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  background: #000;
  display: flex;
  align-items: center;
  padding: 0 10px;
  box-sizing: border-box;
}

.SequencerTimeBarRight {
  flex: 1;
  min-width: 0;
  padding: 4px 0;
  background: #000;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.SequencerZoomLayer {
  position: relative;
  z-index: 20;
  width: 100%;
  height: 12px;
  background: #1a1a1a;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.75);
  overflow: hidden;
}

.SequencerTimeBarTrack {
  width: 100%;
  height: 24px;
  border-radius: 6px;
  background: #1a1a1a;
  border: 1px solid rgba(255, 255, 255, 0.18);
  position: relative;
  overflow: hidden;
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.75);
  z-index: 10;
}

.SequencerTimelineScrollbarWindow {
  position: absolute;
  top: 1px;
  bottom: 1px;
  min-width: 0;
  background: #002424;
  opacity: 1;
  border-radius: 9px;
  cursor: grab;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.7);
  z-index: 4;
}

.SequencerTimelineScrollbarWindow:hover {
  background: #597d7d;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.75), 0 0 0 2px rgba(255, 255, 255, 0.12);
}

.SequencerTimelineScrollbarWindow:active {
  background: #809292;
  cursor: grabbing;
}

.SequencerTimelineScrollbarHandle {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 10px;
  background: #001616;
  cursor: ew-resize;
  z-index: 5;
}

.SequencerTimelineScrollbarHandle:hover {
