function getKeyframeColor(paramId: string, candidates: Array<{id: string; label: string}>): string {
  const idx = candidates.findIndex(c => c.id === paramId);
  if (idx < 0) return '#bae1ff';
  return KEYFRAME_COLORS[idx % KEYFRAME_COLORS.length];
}

// Per-param color cache for timeline clip rendering — ensures consistent color per paramId across clips
const paramLevelColors: Record<string, string> = {};
function getKeyframeColorByIndex(index: number): string {
  return KEYFRAME_COLORS[index % KEYFRAME_COLORS.length];
}

function getKeyframeCandidatesForPreset(
  preset: AnyPreset | undefined | null,
  getShaderById: (id: string) => any,
  isCompositePreset: (p: any) => boolean,
  globalParamDefs: Array<{ id: string; label: string; category?: string }>
): Array<{ id: string; label: string }> {
  if (!preset) return [];
  if (isCompositePreset(preset)) {
    const composite = preset as CompositePreset;
    const out: Array<{ id: string; label: string }> = [];
    (composite.layers || []).forEach((layer, i) => {
      const shader = getShaderById(layer.shaderId);
      const layerLabel = layer.name || `Layer ${i + 1}`;
      (shader?.parameters || []).forEach((param: any) => {
        out.push({ id: `composite_${i}_${param.id}`, label: `${layerLabel} · ${param.label}` });
      });
      globalParamDefs.forEach(param => {
        out.push({ id: `compositeG_${i}_${param.id}`, label: `${layerLabel} · Global · ${param.label}` });
      });
    });
    return out;
  }
  const shader = getShaderById(preset.shaderId);
  const out: Array<{ id: string; label: string }> = [];
  (shader?.parameters || []).forEach((param: any) => {
    out.push({ id: param.id, label: param.label });
  });
  globalParamDefs.forEach(param => {
    out.push({ id: `global_${param.id}`, label: `Global · ${param.label}` });
  });
  return out;
}

function createId(prefix: string): string {
  return `${prefix}_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

function normalizePreviewHardwareMetrics(payload: any): PreviewHardwareMetrics {
  return {
    cpuUsagePercent: typeof payload?.cpuUsagePercent === 'number' ? payload.cpuUsagePercent : null,
    memoryUsedGb: typeof payload?.memoryUsedGb === 'number' ? payload.memoryUsedGb : null,
    memoryTotalGb: typeof payload?.memoryTotalGb === 'number' ? payload.memoryTotalGb : null,
    memoryUsagePercent: typeof payload?.memoryUsagePercent === 'number' ? payload.memoryUsagePercent : null,
    temperatureCelsius: typeof payload?.temperatureCelsius === 'number' ? payload.temperatureCelsius : null,
    temperatureAvailable: Boolean(payload?.temperatureAvailable),
    source: payload?.source === 'electron' ? 'electron' : 'browser'
  };
}

function readBrowserHardwareMetrics(): PreviewHardwareMetrics {
  const perfMemory = (performance as Performance & {
    memory?: {
      usedJSHeapSize?: number;
      totalJSHeapSize?: number;
    };
  }).memory;

  const usedBytes = perfMemory?.usedJSHeapSize;
  const totalBytes = perfMemory?.totalJSHeapSize;
  const hasMemory = typeof usedBytes === 'number' && typeof totalBytes === 'number' && totalBytes > 0;
  const toGb = (value: number) => Math.round((value / (1024 * 1024 * 1024)) * 10) / 10;

  return {
    cpuUsagePercent: null,
    memoryUsedGb: hasMemory ? toGb(usedBytes) : null,
    memoryTotalGb: hasMemory ? toGb(totalBytes) : null,
    memoryUsagePercent: hasMemory ? Math.round((usedBytes / totalBytes) * 1000) / 10 : null,
    temperatureCelsius: null,
    temperatureAvailable: false,
    source: 'browser'
  };
}

function formatClock(ms: number) {
  const totalMs = Math.max(0, Math.floor(ms));
  const totalSeconds = Math.floor(totalMs / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const cent = Math.floor((totalMs % 1000) / 10);
  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${cent.toString().padStart(2, '0')}`;
}

function formatClockMs(ms: number) {
  const totalMs = Math.max(0, Math.floor(ms));
  const totalSeconds = Math.floor(totalMs / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const millis = totalMs % 1000;
  return `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}.${millis.toString().padStart(3, '0')}`;
}

function parseTimecodeToMs(input: string) {
  const raw = String(input || '').trim();
  if (!raw) return null;

  if (/^\d+$/.test(raw)) {
    const n = Number(raw);
    return isFinite(n) ? Math.max(0, Math.floor(n)) : null;
  }

  const normalized = raw.replace(',', '.');
  const parts = normalized.split(':').map(s => s.trim()).filter(Boolean);
  if (!parts.length) return null;

  const last = parts[parts.length - 1];
  const lastParts = last.split('.');
  const secStr = (lastParts[0] || '').trim();
  const fracStr = (lastParts[1] || '').trim();

  const sec = Number(secStr);
  if (!isFinite(sec)) return null;

  let ms = 0;
  if (fracStr) {
    const padded = (fracStr + '000').slice(0, 3);
    const n = Number(padded);
    if (!isFinite(n)) return null;
    ms = n;
  }

  let s = sec;
  let m = 0;
  let h = 0;
  if (parts.length === 2) {
    m = Number(parts[0]);
    if (!isFinite(m)) return null;
  } else if (parts.length >= 3) {
    h = Number(parts[parts.length - 3]);
    m = Number(parts[parts.length - 2]);
    if (!isFinite(h) || !isFinite(m)) return null;
  }

  const total = (((h * 60 + m) * 60) + s) * 1000 + ms;
  return isFinite(total) ? Math.max(0, Math.floor(total)) : null;
}

const DEFAULT_CLIP_DURATION_MS = 2000;
const DEFAULT_TAG_DURATION_MS = DEFAULT_CLIP_DURATION_MS;
const DEFAULT_PIXELS_PER_SECOND = 120;
const MAX_PIXELS_PER_SECOND = 20000;
const TRACK_LABEL_WIDTH_PX = 220;

function buildDefaultSequence(): TimelineSequence {
  const t1: TimelineTrack = { id: 't1', name: 'Layer 1', clips: [], collapsed: false, brightness: 1, muted: false, solo: false, blendMode: 1 };
  const t2: TimelineTrack = { id: 't2', name: 'Layer 2', clips: [], collapsed: false, brightness: 1, muted: false, solo: false, blendMode: 1 };
  return { version: 1, tracks: [t1, t2], tags: [] };
}

function getTrackEndMs(track: TimelineTrack) {
  let end = 0;
  for (const c of track.clips) end = Math.max(end, c.startMs + c.durationMs);
  return end;
}

function findClip(sequence: TimelineSequence, clipId: string) {
  for (const track of sequence.tracks) {
    const clip = track.clips.find(c => c.id === clipId);
    if (clip) return { track, clip };
  }
  return null;
}

function normalizeTrack(track: TimelineTrack): TimelineTrack {
  const clips = track.clips
    .map(c => ({ ...c }))
    .sort((a, b) => a.startMs - b.startMs);

  let cursor = 0;
  for (const clip of clips) {
    const start = Math.max(0, clip.startMs);
    clip.startMs = start < cursor ? cursor : start;
    cursor = clip.startMs + Math.max(1, clip.durationMs);
  }

  return { ...track, clips };
}

function sortTrackOnly(track: TimelineTrack): TimelineTrack {
  const clips = track.clips
    .map(c => ({ ...c }))
    .sort((a, b) => a.startMs - b.startMs);
  return { ...track, clips };
}


function normalizeTags(tags: TimelineTag[] | undefined): TimelineTag[] {
  const next = (tags || [])
    .filter(t => t && typeof t.tMs === 'number' && isFinite(t.tMs))
    .map(t => ({
      ...t,
      tMs: Math.max(0, t.tMs),
      durationMs: (typeof (t as any).durationMs === 'number' && isFinite((t as any).durationMs)) ? Math.max(1, (t as any).durationMs) : DEFAULT_TAG_DURATION_MS
    }))
    .sort((a, b) => a.tMs - b.tMs);
  return next;
}

function normalizeSequence(seq: TimelineSequence): TimelineSequence {
  const tracks = (seq.tracks || []).map(t => sortTrackOnly(t));
  const tags = normalizeTags((seq as any).tags);
  return { ...seq, version: 1, tracks, tags };
}

function normalizePresetForTransport(presetAny: AnyPreset): AnyPreset {
  if (!presetAny) return presetAny;

  if (isSequencePreset(presetAny)) return presetAny;

  if (isCompositePreset(presetAny as any)) {
    const comp = presetAny as CompositePreset;
    const params = { ...(comp.parameters || {}) } as any;
    if (params.fileMap instanceof Map) params.fileMap = Array.from(params.fileMap.entries());
    const layers = (comp.layers || []).map(layer => normalizePresetForTransport(layer as any) as ShaderPreset);
    return { ...comp, parameters: params, layers };
  }

  const preset = presetAny as ShaderPreset;
  const params = { ...(preset.parameters || {}) } as any;
  if (params.fileMap instanceof Map) params.fileMap = Array.from(params.fileMap.entries());
  return { ...preset, parameters: params };
}

function getSequenceSignature(seq: TimelineSequence): string {
  const trackSig = (seq.tracks || [])
    .map(tr => {
      const clipsSig = (tr.clips || []).map(c => `${c.id}:${Math.round(c.startMs)}:${Math.round(c.durationMs)}:${c.presetId || ''}`).join(',');
      return `${tr.id}:${encodeURIComponent(tr.name || '').slice(0, 60)}:${tr.muted ? 1 : 0}:${tr.solo ? 1 : 0}:${tr.collapsed ? 1 : 0}:${Number(tr.brightness ?? 1).toFixed(4)}:${tr.blendMode ?? 1}:${clipsSig}`;
    })
    .join('|');
  const tagsSig = ((seq as any).tags || [])
    .map((tg: any) => `${tg.id}:${Math.round(Number(tg.tMs || 0))}:${Math.round(Number(tg.durationMs || 0))}:${encodeURIComponent(String(tg.label || '')).slice(0, 120)}`)
    .join('|');
  return `${trackSig}||${tagsSig}`;
}

