  const sessionId = getCurrentSessionId() || 'default';
  return `volumetric_sequencer_recovery_${sessionId}`;
}

function describeSequenceChange(before: TimelineSequence, after: TimelineSequence): string {
  const bt = before.tracks || [];
  const at = after.tracks || [];
  if (bt.length !== at.length) return at.length > bt.length ? 'Agregar layer' : 'Eliminar layer';

  for (let i = 0; i < Math.min(bt.length, at.length); i++) {
    const b = bt[i];
    const a = at[i];
    if (
      b.id !== a.id ||
      (b.name || '') !== (a.name || '') ||
      !!b.muted !== !!a.muted ||
      !!b.solo !== !!a.solo ||
      !!b.collapsed !== !!a.collapsed ||
      Number(b.brightness ?? 1) !== Number(a.brightness ?? 1) ||
      Number(b.blendMode ?? 1) !== Number(a.blendMode ?? 1)
    ) {
      return 'Editar layer';
    }
  }

  const beforeClips = new Map<string, { trackId: string; startMs: number; durationMs: number }>();
  for (const tr of bt) {
    for (const c of tr.clips || []) beforeClips.set(c.id, { trackId: tr.id, startMs: c.startMs, durationMs: c.durationMs });
  }

  const afterClips = new Map<string, { trackId: string; startMs: number; durationMs: number }>();
  for (const tr of at) {
    for (const c of tr.clips || []) afterClips.set(c.id, { trackId: tr.id, startMs: c.startMs, durationMs: c.durationMs });
  }

  let added = 0;
  let removed = 0;
  let moved = 0;
  let resized = 0;

  for (const [id, b] of beforeClips.entries()) {
    if (!afterClips.has(id)) removed++;
    else {
      const a = afterClips.get(id)!;
      if (a.trackId !== b.trackId || Math.round(a.startMs) !== Math.round(b.startMs)) moved++;
      if (Math.round(a.durationMs) !== Math.round(b.durationMs)) resized++;
    }
  }
  for (const id of afterClips.keys()) {
    if (!beforeClips.has(id)) added++;
  }

  if (added && !removed) return added === 1 ? 'Agregar clip' : `Agregar ${added} clips`;
  if (removed && !added) return removed === 1 ? 'Eliminar clip' : `Eliminar ${removed} clips`;
  if ((added || removed) && moved) return 'Reacomodar clips';
  if (moved) return moved === 1 ? 'Mover clip' : `Mover ${moved} clips`;
  if (resized) return resized === 1 ? 'Cambiar duración' : `Cambiar duración (${resized})`;

  const bTags = ((before as any).tags || []) as Array<{ id: string; tMs: number; durationMs?: number; label?: string }>;
  const aTags = ((after as any).tags || []) as Array<{ id: string; tMs: number; durationMs?: number; label?: string }>;
  if (bTags.length !== aTags.length) return aTags.length > bTags.length ? 'Agregar TAG' : 'Eliminar TAG';
  for (let i = 0; i < Math.min(bTags.length, aTags.length); i++) {
    const b = bTags[i];
    const a = aTags[i];
    if (b.id !== a.id) return 'Editar TAGs';
    if (Math.round(Number(b.tMs || 0)) !== Math.round(Number(a.tMs || 0))) return 'Mover TAG';
    if (Math.round(Number(b.durationMs || 0)) !== Math.round(Number(a.durationMs || 0))) return 'Cambiar duración TAG';
    if (String(b.label || '') !== String(a.label || '')) return 'Renombrar TAG';
  }

  return 'Cambio';
}

