          }
          const prevIdx = (idx - 1 + segs.length) % segs.length;
          applySeek(segs[prevIdx].startMs);
          return;
        }

        const nextIdx = (idx + 1) % segs.length;
        applySeek(segs[nextIdx].startMs);
      }
    };
