        const outSig = `${outputPreset.outputWidth}:${outputPreset.outputHeight}:${outputPreset.invertRows ? 1 : 0}:${outputPreset.resolutionX || 0}:${outputPreset.resolutionY || 0}:${outputPreset.resolutionZ || 0}:${outputPreset.layers?.length || 1}`;
