        return `sequencer:${isMasterClient ? 1 : 0}:${isPlaying ? 1 : 0}:${loop ? 1 : 0}:${showTagsInOutput ? 1 : 0}:${tSig}:${seqSig}:${tagsSig}:${presetsSig}:${outSig}:${vizSig}:${perfSig}`;
