          enabled: !!(defaults.audioParams as any).audioEnabled,
          bpm: Number((defaults.audioParams as any).bpm ?? defaultGlobal.audio.bpm),
          sensitivity: Number((defaults.audioParams as any).audioSensitivity ?? defaultGlobal.audio.sensitivity)
        };

        const baseState = {
          activeMode: 'sequencer',
          renderMode: RENDER_MODES.PERFORMANCE,
          visualization,
          colors,
          audio,
          particles: remoteState?.particles ?? defaultGlobal.particles,
          outputPreset,
          camera: {
            position: cameraPosition,
            zoom: cameraZoom,
            autoRotateYaw,
            autoRotatePitch
          },
          viewMode,
          vizPerformanceSettings: performanceSettings,
          sequencerTags: {
            enabled: showTagsInOutput,
            activeLabel: activeTagLabel,
            isPlaying,
            tMs: materializedPlayheadMs
          }
        };

        const seqSig = sequence.tracks
          .map(tr => `${tr.id}:${tr.muted ? 1 : 0}:${tr.solo ? 1 : 0}:${tr.brightness ?? 1}:${tr.blendMode ?? 1}:${tr.clips.map(c => `${c.id}:${Math.round(c.startMs)}:${Math.round(c.durationMs)}:${c.presetId || ''}`).join(',')}`)
          .join('|');
        const tagsSig = (sequence.tags || []).map(tg => `${tg.id}:${Math.round(tg.tMs)}:${Math.round((tg as any).durationMs ?? 0)}:${encodeURIComponent(tg.label || '').slice(0, 120)}`).join('|');
        const timelineSig = `${seqSig}||${tagsSig}`;

        const update: any = {
          ...baseState,
          activeLayerPresets,
          shaderId: activeLayerPresets[0]?.shaderId || 'menger',
          params: activeLayerPresets[0]?.parameters || {},
          sequencerMeta: { loop }
        };

        if (lastSentSequenceSigRef.current !== timelineSig) {
          lastSentSequenceSigRef.current = timelineSig;
          update.sequencerSequence = sequence;
        }

        return update;
      }
