      const def = globalParamDefs.find(p => p.id === id);
      const gs = (selectedPresetForPanel as any).globalSettings || {};
      const colors = (selectedPresetForPanel as any).colors || {};
      const v = id === 'raymarchColor1'
        ? (colors.color1 ?? gs.raymarchColor1 ?? def?.defaultValue)
        : id === 'raymarchColor2'
          ? (colors.color2 ?? gs.raymarchColor2 ?? def?.defaultValue)
          : (gs[id] ?? def?.defaultValue);
      const num = typeof v === 'number' ? v : Number(v);
      return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
    }

    if (paramKey.startsWith('compositeG_')) {
      const match = paramKey.match(/^compositeG_(\d+)_(.+)$/);
      if (!match) return undefined;
      const layerIndex = Number(match[1]);
      const id = match[2];
      const def = globalParamDefs.find(p => p.id === id);
      const composite = selectedPresetForPanel as any;
      const layer = composite.layers?.[layerIndex];
      const gs = layer?.globalSettings || {};
      const colors = layer?.colors || {};
      const v = id === 'raymarchColor1'
        ? (colors.color1 ?? gs.raymarchColor1 ?? def?.defaultValue)
        : id === 'raymarchColor2'
          ? (colors.color2 ?? gs.raymarchColor2 ?? def?.defaultValue)
          : (gs[id] ?? def?.defaultValue);
      const num = typeof v === 'number' ? v : Number(v);
      return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
    }

    if (isCompositePreset(selectedPresetForPanel as any) && /^composite_\d+_/.test(paramKey)) {
      const match = paramKey.match(/^composite_(\d+)_(.+)$/);
      if (!match) return undefined;
      const layerIndex = Number(match[1]);
      const innerId = match[2];
      const composite = selectedPresetForPanel as any;
      const layer = composite.layers?.[layerIndex];
      const shader = layer?.shaderId ? getShaderById(layer.shaderId) : undefined;
      const def = shader?.parameters?.find((p: any) => p.id === innerId);
      const base = layer?.parameters?.[innerId];
      const v = base !== undefined ? base : def?.defaultValue;
      const num = typeof v === 'number' ? v : Number(v);
      return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
    }

    const shader = getShaderById(selectedPresetForPanel.shaderId);
    const def = shader?.parameters?.find((p: any) => p.id === paramKey);
    const base = (selectedPresetForPanel as any).parameters?.[paramKey];
    const v = base !== undefined ? base : def?.defaultValue;
    const num = typeof v === 'number' ? v : Number(v);
    return typeof v === 'boolean' ? v : (isFinite(num) && String(v).trim() !== '' ? num : v);
  }, [selectedPresetForPanel, globalParamDefs]);

  const addKeyframeForParamKey = useCallback((paramKey: string) => {
    if (!selected) return;
    const localT = Math.max(0, playheadMs - selected.clip.startMs);
    const value = resolveKeyframeValue(paramKey);
    if (value === undefined) return;
    // Normalize the value based on parameter range before storing
    const normalized = (() => {
      if (typeof value !== 'number') return value;
      if (paramKey.startsWith('global_') || paramKey.startsWith('compositeG_')) return value; // Global params stored as absolute
      const shaderId = selectedPresetForPanel?.shaderId;
      if (!shaderId) return value;
      const shader = getShaderById(shaderId);
      const def = shader?.parameters?.find((p: any) => p.id === paramKey);
      if (!def || (def.type !== 'number' && def.type !== 'float')) return value;
      if (typeof def.min !== 'number' || typeof def.max !== 'number' || def.max <= def.min) return value;
      return Math.max(0, Math.min(1, (value - def.min) / (def.max - def.min)));
    })();
    upsertKeyframeForSelectedClip(paramKey, normalized, localT);
    setKfParamId(paramKey);
    setSelectedKeyframeTMs(localT);
  }, [selected, playheadMs, resolveKeyframeValue, upsertKeyframeForSelectedClip, selectedPresetForPanel]);

  const handleKeyframeAdd = useCallback((paramId: string, normalizedValue: number, localTMs: number) => {
    // Value is already normalized (0.0-1.0), store directly
    upsertKeyframeForSelectedClip(paramId, normalizedValue, localTMs);
    setKfParamId(paramId);
    setSelectedKeyframeTMs(localTMs);
  }, [upsertKeyframeForSelectedClip]);

  const handleKeyframeUpdate = useCallback((paramId: string, localTMs: number, newNormalizedValue: number) => {
    // Value is already normalized (0.0-1.0), store directly
    upsertKeyframeForSelectedClip(paramId, newNormalizedValue, localTMs);
  }, [upsertKeyframeForSelectedClip]);

  const handleKeyframeDelete = useCallback((paramId: string, localTMs: number) => {
    deleteKeyframe(paramId, localTMs);
  }, []);

  const addKeyframeToSelectedClip = () => {
    addKeyframeForParamKey(kfParamId);
  };

  const clearKeyframesForParamKey = useCallback((paramKey: string) => {
    if (!selected) return;
    const { track, clip } = selected;
    setSequence(prev => ({
      ...prev,
      tracks: prev.tracks.map(t => {
        if (t.id !== track.id) return t;
        const nextClips = t.clips.map(c => {
          if (c.id !== clip.id) return c;
          const nextKeyframes = { ...(c.keyframes || {}) } as Record<string, Array<{ tMs: number; value: any }>>;
          delete nextKeyframes[paramKey];
          return { ...c, keyframes: nextKeyframes };
        });
        return { ...t, clips: nextClips };
      })
    }));
    if (paramKey === kfParamId) setSelectedKeyframeTMs(null);
  }, [selected, kfParamId]);

  const setKeyframesForSelectedClipParam = useCallback((paramKey: string, frames: Array<{ tMs: number; value: any }>) => {
    if (!selected) return;
    const { track, clip } = selected;
    const nextFrames = frames
      .filter(f => f && typeof f.tMs === 'number' && isFinite(f.tMs))
      .map(f => ({ tMs: Math.max(0, Math.min(clip.durationMs, f.tMs)), value: f.value }))
      .sort((a, b) => a.tMs - b.tMs);

    setSequence(prev => {
      const nextTracks = prev.tracks.map(t => {
        if (t.id !== track.id) return t;
        const nextClips = t.clips.map(c => {
          if (c.id !== clip.id) return c;
          const nextKeyframes = { ...(c.keyframes || {}) } as Record<string, Array<{ tMs: number; value: any }>>;
          nextKeyframes[paramKey] = nextFrames;
          return { ...c, keyframes: nextKeyframes };
        });
        return { ...t, clips: nextClips };
      });
      return { ...prev, tracks: nextTracks };
    });
    setSelectedKeyframeTMs(nextFrames.length ? nextFrames[nextFrames.length - 1].tMs : null);
  }, [selected]);

  const applyKeyframePreset = useCallback((preset: 'rampUp' | 'rampDown' | 'easeInUp' | 'easeOutUp' | 'easeInDown' | 'easeOutDown' | 'oscillate') => {
    if (!selected) return;
    const dur = Math.max(1, selected.clip.durationMs);
    // Keyframe values are normalized (0.0-1.0), presets use 0 and 1
    const isDown = preset === 'rampDown' || preset === 'easeInDown' || preset === 'easeOutDown';
    const startValue = isDown ? 1 : 0;
    const targetValue = isDown ? 0 : 1;

    if (preset === 'oscillate') {
      const min = Math.min(startValue, targetValue);
      const max = Math.max(startValue, targetValue);
      const center = (min + max) / 2;
      const amp = (max - min) / 2;
      const cycles = 2;
      const sampleCount = 17;
      const frames: Array<{ tMs: number; value: number }> = [];
      for (let i = 0; i < sampleCount; i++) {
        const tNorm = i / (sampleCount - 1);
        const phase = (-Math.PI / 2) + tNorm * Math.PI * 2 * cycles;
        const v = center + amp * Math.sin(phase);
        frames.push({ tMs: tNorm * dur, value: v });
      }
      setKeyframesForSelectedClipParam(kfParamId, frames);
      return;
    }

    const ease = (t: number) => {
      if (preset === 'easeInUp' || preset === 'easeInDown') return t * t;
      if (preset === 'easeOutUp' || preset === 'easeOutDown') return 1 - (1 - t) * (1 - t);
      return t;
    };

    const sampleCount = preset === 'rampUp' || preset === 'rampDown' ? 2 : 5;
    const frames: Array<{ tMs: number; value: number }> = [];
    for (let i = 0; i < sampleCount; i++) {
      const tNorm = i / (sampleCount - 1);
      const tMs = tNorm * dur;
      const v = startValue + (targetValue - startValue) * ease(tNorm);
      frames.push({ tMs, value: v });
    }
    setKeyframesForSelectedClipParam(kfParamId, frames);
  }, [selected, kfParamId, resolveKeyframeValue, setKeyframesForSelectedClipParam]);

  const deleteKeyframeAtTime = (tMs: number) => {
    if (!selected) return;
    const { track, clip } = selected;
    setSequence(prev => {
      const nextTracks = prev.tracks.map(t => {
        if (t.id !== track.id) return t;
        const nextClips = t.clips.map(c => {
          if (c.id !== clip.id) return c;
          const nextKeyframes = { ...(c.keyframes || {}) } as Record<string, Array<{ tMs: number; value: any }>>;
          for (const pid of Object.keys(nextKeyframes)) {
            const frames = (nextKeyframes[pid] || []).filter(f => f.tMs !== tMs);
            if (frames.length === 0) delete nextKeyframes[pid];
            else nextKeyframes[pid] = frames;
          }
          return { ...c, keyframes: nextKeyframes };
        });
        return { ...t, clips: nextClips };
      });
      return { ...prev, tracks: nextTracks };
    });
  };

  const deleteKeyframe = (paramId: string, tMs: number) => {
    if (!selected) return;
    const { track, clip } = selected;
    setSequence(prev => {
      const nextTracks = prev.tracks.map(t => {
        if (t.id !== track.id) return t;
        const nextClips = t.clips.map(c => {
          if (c.id !== clip.id) return c;
          const nextKeyframes = { ...(c.keyframes || {}) };
          const frames = (nextKeyframes[paramId] || []).filter(f => f.tMs !== tMs);
          if (frames.length === 0) delete nextKeyframes[paramId];
          else nextKeyframes[paramId] = frames;
          return { ...c, keyframes: nextKeyframes };
        });
        return { ...t, clips: nextClips };
      });
      return { ...prev, tracks: nextTracks };
    });
  };

  const updateSelectedClipPreset = useCallback((apply: (preset: ShaderPreset) => ShaderPreset) => {
    if (!selectedClipId) return;
    setSequence(prev => {
      let changed = false;
      const nextTracks = prev.tracks.map(t => {
        const nextClips = t.clips.map(c => {
          if (c.id !== selectedClipId) return c;
          const base = c.preset ?? (c.presetId ? (presetsById.get(c.presetId) ?? null) : null);
          if (!base || isSequencePreset(base)) return c;
          const basePreset = clonePreset(base) as ShaderPreset;
          const nextPreset = apply(basePreset);
          changed = true;
          return { ...c, preset: nextPreset };
        });
        return t.clips === nextClips ? t : { ...t, clips: nextClips };
      });
      if (changed) setParamVersion(v => v + 1);
      return changed ? { ...prev, tracks: nextTracks } : prev;
    });
  }, [selectedClipId, presetsById]);

  const onSelectedClipParameterChange = useCallback((paramId: string, value: any) => {
    if (!selected) return;
    updateSelectedClipPreset((presetAny) => {
      if (isCompositePreset(presetAny as any) && /^composite_\d+_/.test(paramId)) {
        const match = paramId.match(/^composite_(\d+)_(.+)$/);
        if (!match) return presetAny;
        const layerIndex = Number(match[1]);
        const innerId = match[2];
        const composite = presetAny as any;
        const layers = (composite.layers || []).map((l: any, idx: number) => {
          if (idx !== layerIndex) return l;
          return { ...l, parameters: { ...(l.parameters || {}), [innerId]: value } };
        });
        return { ...composite, layers };
      }
      const preset = presetAny as any;
      return { ...preset, parameters: { ...(preset.parameters || {}), [paramId]: value } };
    });
    if (selected && (autoKeyframe || selectedKeyframeTMs != null)) {
      const localT = selectedKeyframeTMs != null ? selectedKeyframeTMs : Math.max(0, playheadMs - selected.clip.startMs);
      // Normalize for shader parameters
      const normalizedValue = (() => {
        if (typeof value !== 'number' || paramId.startsWith('global_') || paramId.startsWith('compositeG_')) return value;
        const shaderId = selectedPresetForPanel?.shaderId;
        if (!shaderId) return value;
        const shader = getShaderById(shaderId);
        const def = shader?.parameters?.find((p: any) => p.id === paramId);
        if (!def || (def.type !== 'number' && def.type !== 'float')) return value;
        if (typeof def.min !== 'number' || typeof def.max !== 'number' || def.max <= def.min) return value;
        return Math.max(0, Math.min(1, (value - def.min) / (def.max - def.min)));
      })();
      upsertKeyframeForSelectedClip(paramId, normalizedValue, localT);
      setSelectedKeyframeTMs(localT);
    }
  }, [updateSelectedClipPreset, selected, autoKeyframe, selectedKeyframeTMs, playheadMs, upsertKeyframeForSelectedClip, selectedPresetForPanel]);

  const onSelectedClipGlobalSettingChange = useCallback((settingKey: string, value: any) => {
    if (!selected) return;
    updateSelectedClipPreset((presetAny) => {
      if (isCompositePreset(presetAny as any) && /^composite_\d+_/.test(settingKey)) {
        const match = settingKey.match(/^composite_(\d+)_(.+)$/);
        if (!match) return presetAny;
        const layerIndex = Number(match[1]);
        const innerId = match[2];
        const composite = presetAny as any;
        const layers = (composite.layers || []).map((l: any, idx: number) => {
          if (idx !== layerIndex) return l;
          const nextGlobal = { ...(l.globalSettings || {}), [innerId]: value };
          const nextColors = { ...(l.colors || {}) };
          if (innerId === 'raymarchColor1') nextColors.color1 = value;
          if (innerId === 'raymarchColor2') nextColors.color2 = value;
          return { ...l, globalSettings: nextGlobal, colors: nextColors };
        });
        return { ...composite, layers };
      }
      const preset = presetAny as any;
      const nextGlobal = { ...(preset.globalSettings || {}), [settingKey]: value };
      const nextColors = { ...(preset.colors || {}) };
      if (settingKey === 'raymarchColor1') nextColors.color1 = value;
      if (settingKey === 'raymarchColor2') nextColors.color2 = value;
      return { ...preset, globalSettings: nextGlobal, colors: nextColors };
    });
    if (selected && (autoKeyframe || selectedKeyframeTMs != null)) {
      const localT = selectedKeyframeTMs != null ? selectedKeyframeTMs : Math.max(0, playheadMs - selected.clip.startMs);
      const key = /^composite_\d+_/.test(settingKey)
        ? settingKey.replace(/^composite_(\d+)_(.+)$/, 'compositeG_$1_$2')
        : `global_${settingKey}`;
      upsertKeyframeForSelectedClip(key, value, localT);
      setSelectedKeyframeTMs(localT);
    }
  }, [updateSelectedClipPreset, selected, autoKeyframe, selectedKeyframeTMs, playheadMs, upsertKeyframeForSelectedClip]);

  const onSelectedClipAnimationStatesChange = useCallback((states: any) => {
    if (!selected) return;
    updateSelectedClipPreset((presetAny) => {
      const preset = presetAny as any;
      return { ...preset, animationStates: states };
    });
  }, [updateSelectedClipPreset]);

  const onResetSelectedClipPreset = useCallback(() => {
    if (!selectedClipId) return;
    setSequence(prev => {
      let changed = false;
      const nextTracks = prev.tracks.map(t => {
        const nextClips = t.clips.map(c => {
          if (c.id !== selectedClipId) return c;
          const presetId = c.presetId ?? c.preset?.id;
          if (!presetId) return c;
          const original = presetsById.get(presetId) ?? null;
          if (!original || isSequencePreset(original)) return c;
          changed = true;
          return { ...c, preset: clonePreset(original) as ShaderPreset };
        });
        return t.clips === nextClips ? t : { ...t, clips: nextClips };
      });
      return changed ? { ...prev, tracks: nextTracks } : prev;
    });
  }, [selectedClipId, presetsById]);

  const exportSequenceAsJson = useCallback(() => {
    try {
      const exportData = {
        type: 'volumetric_sequence_preset',
        version: 1,
        name: loadedSequencePreset?.name || 'Sequence',
        sequence: clonePreset(sequence),
        outputPreset: {
          outputWidth: outputPreset.outputWidth,
          outputHeight: outputPreset.outputHeight,
          layers: outputPreset.layers,
          invertRows: outputPreset.invertRows,
          resolutionX: outputPreset.resolutionX,
          resolutionY: outputPreset.resolutionY,
          resolutionZ: outputPreset.resolutionZ,
          spoutEnabled: outputPreset.spoutEnabled,
          spoutName: outputPreset.spoutName,
          spoutWidth: outputPreset.spoutWidth,
          spoutHeight: outputPreset.spoutHeight
        }
      };
      const dataStr = JSON.stringify(exportData, null, 2);
      const blob = new Blob([dataStr], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      const safeName = (loadedSequencePreset?.name || 'Sequence').replace(/[^a-z0-9_\-\s]/gi, '_');
      a.download = `volumetric_sequence_${safeName}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      console.error('Error exporting sequence', e);
      alert(t('sequencer.exportError', 'Error al exportar la secuencia'));
    }
  }, [sequence, loadedSequencePreset, outputPreset, t]);

  const importSequenceFromJson = useCallback(() => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json,application/json';
    input.onchange = async (e: any) => {
      const file = e.target.files?.[0];
      if (!file) return;
      try {
        const text = await file.text();
        const data = JSON.parse(text);
        if (data && (data.type === 'volumetric_sequence_preset' || (data.sequence && data.sequence.tracks))) {
          const importedSequence = data.sequence || data;
          const next = normalizeSequence(clonePreset(importedSequence));
          const importedName = String(data.name || file.name.replace(/\.[^.]+$/, '') || t('sequencer.newSequence', 'Nueva Secuencia')).trim();
          const importedOutputPreset = data.outputPreset
            ? cloneOutputPresetSnapshot(data.outputPreset as OutputPreset)
            : cloneOutputPresetSnapshot(outputPreset);

          setSequence(next);
          setLoadedSequencePresetId(null);
          setImportedSequenceName(importedName);
          setSelectedTrackId(next.tracks[0]?.id || 't1');
          setSelectedClipId(null);
          setSelectedClipIds([]);
          setSelectedTagId(null);
          setEditingTagId(null);
          setPlay(false);
          setPlayheadImmediate(0);
          setOutputPreset(importedOutputPreset as OutputPreset);

          const preset: SequencePreset = {
            id: createId('seq'),
            name: importedName,
            shaderId: 'sequencer_timeline',
            isSequence: true,
            sequence: next,
            createdAt: Date.now(),
            updatedAt: Date.now(),
            sessionId: getCurrentSessionId(),
            outputPreset: importedOutputPreset
          };

          const saved = await PresetManager.savePreset(preset);
          if (saved) {
            await persistSavedSequenceState(preset);
            alert(t('sequencer.importSuccess', 'Secuencia importada correctamente'));
          } else {
            setSavedDocumentSignature(null);
            alert(t('sequencer.importRecovery', 'Secuencia importada. No se pudo persistir en el servidor, pero quedo guardada como borrador local de recuperacion.'));
          }
        } else {
          alert(t('sequencer.importInvalid', 'Estructura de archivo JSON inválida'));
        }
      } catch (err) {
        console.error('Error importing sequence', err);
        alert(t('sequencer.importParseError', 'Error al procesar el archivo JSON'));
      }
    };
    input.click();
  }, [outputPreset, persistSavedSequenceState, setPlayheadImmediate, setOutputPreset, t]);

  const resolveCloseRequest = useCallback((shouldClose: boolean) => {
    const resolver = closeRequestResolverRef.current;
    closeRequestResolverRef.current = null;
    closeRequestPromiseRef.current = null;
    setIsCloseConfirmSaving(false);
    setShowCloseConfirmModal(false);
    if (resolver) {
      resolver(shouldClose);
    }
  }, []);

  const handleCloseConfirmSave = useCallback(async () => {
    if (isCloseConfirmSaving) return;
    setIsCloseConfirmSaving(true);
    let saved = false;
    try {
      if (loadedSequencePresetId) {
        saved = await updateLoadedSequencePreset({ silentSuccess: true, silentError: false });
      } else {
        saved = await saveNewSequencePreset({ silentSuccess: true, silentError: false });
      }
    } catch (error) {
      console.error('Error saving sequence during close confirmation:', error);
    }
    if (!saved) {
      saved = persistRecoveryDraftNow();
    }
    if (saved) {
      resolveCloseRequest(true);
      return;
    }
    setIsCloseConfirmSaving(false);
  }, [isCloseConfirmSaving, loadedSequencePresetId, persistRecoveryDraftNow, resolveCloseRequest, saveNewSequencePreset, updateLoadedSequencePreset]);

  useEffect(() => {
    const handleBeforeUnload = (event: BeforeUnloadEvent) => {
      if ((window as any).volumetricElectron || !hasUnsavedChanges) return;
      event.preventDefault();
      event.returnValue = '';
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [hasUnsavedChanges]);

  useEffect(() => {
    const closeBridge = window as any;
    closeBridge.__volumetricHasUnsavedChanges__ = () => hasUnsavedChanges;
    closeBridge.__volumetricSaveBeforeClose__ = async () => {
      discardUnsavedOnCloseRef.current = false;
      setIsCloseConfirmSaving(false);
      setShowCloseConfirmModal(false);
      if (!hasUnsavedChanges) return true;
      try {
        let saved = false;
        if (loadedSequencePresetId) {
          saved = await updateLoadedSequencePreset({ silentSuccess: true, silentError: true });
        } else {
          saved = await saveNewSequencePreset({
            silentSuccess: true,
            silentError: true,
            promptForName: false,
            fallbackName: buildAutoSequenceName()
          });
        }

        if (!saved) {
          persistRecoveryDraftNow();
        }
      } catch (error) {
        console.error('Error in save-before-close sequencer flow:', error);
        persistRecoveryDraftNow();
      }

      // Always allow Electron to complete the close. Persistence fallback already ran above.
      return true;
    };
    closeBridge.__volumetricDiscardBeforeClose__ = async () => {
      discardUnsavedOnCloseRef.current = true;
      setIsCloseConfirmSaving(false);
      setShowCloseConfirmModal(false);
      clearRecoveryDraft();
      return true;
    };
    closeBridge.__volumetricRequestClose__ = () => {
      if (!hasUnsavedChanges) {
        return Promise.resolve(true);
      }
      if (closeRequestPromiseRef.current) {
        return closeRequestPromiseRef.current;
      }
      setIsCloseConfirmSaving(false);
      setShowCloseConfirmModal(true);
      closeRequestPromiseRef.current = new Promise<boolean>((resolve) => {
        closeRequestResolverRef.current = resolve;
      });
      return closeRequestPromiseRef.current;
    };

    return () => {
      if (closeRequestResolverRef.current) {
        closeRequestResolverRef.current(false);
        closeRequestResolverRef.current = null;
      }
      closeRequestPromiseRef.current = null;
      delete closeBridge.__volumetricHasUnsavedChanges__;
      delete closeBridge.__volumetricSaveBeforeClose__;
      delete closeBridge.__volumetricDiscardBeforeClose__;
      delete closeBridge.__volumetricRequestClose__;
    };
  }, [buildAutoSequenceName, clearRecoveryDraft, hasUnsavedChanges, loadedSequencePresetId, persistRecoveryDraftNow, saveNewSequencePreset, updateLoadedSequencePreset]);

  return (
    <div className="SequencerApp">
      <GlobalHeader
        currentPage="sequencer"
        extraActionButtons={[
          {
            title: 'Output Map Configuration',
            ariaLabel: 'Output Map Configuration',
            accent: '#00ffff',
            onClick: () => handleOpenOutputConfig(),
            icon: (
              <svg viewBox="0 0 24 24" aria-hidden="true" className="nav-btn-icon-svg">
                <path d="M14.8 5.2a4.1 4.1 0 0 0-1 4.3l-5.9 5.9a1.7 1.7 0 0 0 0 2.4l.3.3a1.7 1.7 0 0 0 2.4 0l5.9-5.9a4.1 4.1 0 0 0 4.3-1l-2.6-2.6 1.4-2.2-1.6-1.6-2.2 1.4-1-1Z" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" strokeLinecap="round" />
                <path d="m9.8 16.2-2 2" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
              </svg>
            )
          },
          {
            title: showOutputMap ? 'OUTPUT MAP: ON' : 'OUTPUT MAP: OFF',
            ariaLabel: showOutputMap ? 'OUTPUT MAP: ON' : 'OUTPUT MAP: OFF',
