                        role="button"
                        tabIndex={0}
                        draggable
                        onDragStart={(e) => {
                          e.dataTransfer.setData(LAYER_DND_MIME, layer.id);
                          e.dataTransfer.setData('text/plain', layer.id);
                          e.dataTransfer.effectAllowed = 'copy';
                        }}
                        onClick={() => {
                          const trackId = selectedTrackId || sequence.tracks[0]?.id;
                          if (!trackId) return;
                          const endMs = getTrackEndMs(sequence.tracks.find(t => t.id === trackId) || sequence.tracks[0]);
                          addLayerToTrack(layer, trackId, endMs);
                        }}
                        onKeyDown={(e) => {
                          if (e.key !== 'Enter' && e.key !== ' ') return;
                          const trackId = selectedTrackId || sequence.tracks[0]?.id;
                          if (!trackId) return;
                          const endMs = getTrackEndMs(sequence.tracks.find(t => t.id === trackId) || sequence.tracks[0]);
                          addLayerToTrack(layer, trackId, endMs);
                        }}
                        title={layer.sourceProject ? `${layer.name} · ${layer.sourceProject}` : layer.name}
                      >
