              gl={{ alpha: false, preserveDrawingBuffer: true, antialias: true }}
              dpr={1}
              camera={{
                position: (() => {
                  const pos = getWorldCameraPosition(cameraPosition, cameraZoom, cameraBounds);
                  return [pos.x, pos.y, pos.z] as [number, number, number];
                })(),
                fov: 45,
                near: cameraBounds.near,
                far: cameraBounds.far
              }}
            >
              <color attach="background" args={['#000']} />
              <ambientLight intensity={0.5} />
              <pointLight position={[10, 10, 10]} intensity={1} />
              <OrbitControls
                ref={orbitControlsRef}
                enableDamping
                dampingFactor={0.08}
                minDistance={cameraBounds.minDistance}
                maxDistance={cameraBounds.maxDistance}
              />
              <CanvasFpsTracker onUpdate={setPreviewFps} />

