                const params = layer.params || {};
                return (
                  <ParticleSystem
                    key={layer.id}
                    count={Number(params.uParticleCount ?? 200)}
                    speed={Number(params.uParticleSpeed ?? 1.0)}
                    spread={64}
                    particleSize={Number(params.uParticleSize ?? 3.0)}
                    particleColor={String(params.uParticleColor ?? effectiveParticleColor)}
                    forceX={Number(params.uParticleForceX ?? 0)}
                    forceY={Number(params.uParticleForceY ?? 0)}
                    forceZ={Number(params.uParticleForceZ ?? 0)}
                    spawnMode={Number.parseInt(String(params.uParticleSpawnMode ?? '0'))}
