                kaleidoscopeScale={(defaults.kaleidoParams as any).kaleidoscopeScale}
                kaleidoscopeZoom={(defaults.kaleidoParams as any).kaleidoscopeZoom}
                warpEnabled={(defaults.warpParams as any).warpEnabled}
                warpFrequencyX={(defaults.warpParams as any).warpFrequencyX}
                warpFrequencyY={(defaults.warpParams as any).warpFrequencyY}
                warpFrequencyZ={(defaults.warpParams as any).warpFrequencyZ}
                warpAmplitudeX={(defaults.warpParams as any).warpAmplitudeX}
                warpAmplitudeY={(defaults.warpParams as any).warpAmplitudeY}
                warpAmplitudeZ={(defaults.warpParams as any).warpAmplitudeZ}
                warpSpeedX={(defaults.warpParams as any).warpSpeedX}
                warpSpeedY={(defaults.warpParams as any).warpSpeedY}
                warpSpeedZ={(defaults.warpParams as any).warpSpeedZ}
                warpRadialAmplitude={(defaults.warpParams as any).warpRadialAmplitude}
                warpRadialFrequency={(defaults.warpParams as any).warpRadialFrequency}
                warpRadialSpeed={(defaults.warpParams as any).warpRadialSpeed}
                onionEnabled={(defaults.onionParams as any).onionEnabled}
                onionThickness={(defaults.onionParams as any).onionThickness}
              />
            </Canvas>
            <PreviewStatsOverlay
              fps={previewFps}
              metrics={previewHardwareMetrics}
              isOpen={showPreviewStats}
              onToggle={() => setShowPreviewStats(prev => !prev)}
            />
            {/* 3D Viewport Toggle */}
            <div style={{
              position: 'absolute',
              top: 12,
              right: 12,
              zIndex: 10,
              display: 'flex',
              gap: 6,
              alignItems: 'center'
            }}>
              <button
                onClick={() => setShowVolumetricCube(prev => !prev)}
                style={{
                  background: showVolumetricCube ? 'rgba(0,200,255,0.15)' : 'rgba(255,255,255,0.05)',
                  border: `1px solid ${showVolumetricCube ? 'rgba(0,200,255,0.4)' : 'rgba(255,255,255,0.15)'}`,
                  borderRadius: '6px',
                  padding: '5px 9px',
                  cursor: 'pointer',
                  fontSize: '14px',
                  color: showVolumetricCube ? '#00ccff' : '#666',
                  display: 'flex',
                  alignItems: 'center',
                  gap: 5,
                  opacity: 0.7,
                  transition: 'opacity 0.15s, background 0.15s'
                }}
                title={showVolumetricCube ? 'Ocultar render 3D' : 'Mostrar render 3D'}
                onMouseEnter={e => (e.currentTarget.style.opacity = '1')}
                onMouseLeave={e => (e.currentTarget.style.opacity = '0.7')}
              >
                <span>{showVolumetricCube ? '👁️' : '🚫'}</span>
                <span style={{ fontSize: 11, fontWeight: 600 }}>3D</span>
              </button>
            </div>
          </div>

          <div
            className={`SequencerTimelineResizeHandle ${isResizingTimelinePanel ? 'isDragging' : ''}`}
            onMouseDown={(e) => {
              e.preventDefault();
              timelinePanelResizeRef.current = {
                startY: e.clientY,
                startHeight: timelinePanelHeight
              };
              setIsResizingTimelinePanel(true);
            }}
            role="separator"
            aria-orientation="horizontal"
            aria-label="Ajustar altura del timeline"
            title="Arrastra para ajustar la altura del timeline"
          >
            <span className="SequencerTimelineResizeGrip" aria-hidden="true" />
          </div>

          <div
            className={`SequencerTimeline ${selectedClipIds.length ? 'hasClipSelection' : ''} ${isResizingTimelinePanel ? 'isDraggingResize' : ''}`}
            style={{ height: `${timelinePanelHeight}px` }}
          >
            <div className="SequencerTransportBar">
              <div className="SequencerTransportBarLeft">
                <button
                  className={`SequencerSmallButton SequencerTransportButton ${isPlaying ? 'isOn' : ''}`}
                  onClick={() => setPlay(!isPlaying)}
                  title={isPlaying ? t('sequencer.pause', 'Pause') : t('sequencer.play', 'Play')}
                  type="button"
                >
                  <span className="SequencerTransportButtonIcon">{isPlaying ? '⏸' : '▶'}</span>
                  <span className="SequencerTransportButtonLabel">{isPlaying ? 'PAUSE' : 'PLAY'}</span>
                </button>
                <button
                  className="SequencerSmallButton SequencerTransportButton"
                  onClick={() => { setPlay(false); setPlayhead(0); }}
                  title={t('sequencer.stop', 'Stop')}
                  type="button"
                >
                  <span className="SequencerTransportButtonIcon">⏹</span>
                  <span className="SequencerTransportButtonLabel">STOP</span>
                </button>
                <button
                  className={`SequencerSmallButton SequencerTransportButton ${loop ? 'isOn' : ''}`}
                  onClick={() => setLoop(v => !v)}
                  title={loop ? t('sequencer.loopOn', 'Loop: ON') : t('sequencer.loopOff', 'Loop: OFF')}
                  type="button"
                >
                  <span className="SequencerTransportButtonIcon">🔁</span>
                  <span className="SequencerTransportButtonLabel">LOOP</span>
                </button>
                <div className="SequencerTopBarMeta SequencerTransportBarMeta">
                  <span ref={clockRef} className="SequencerTopBarMetaCurrent">{formatClock(playheadMs)}</span>
                  <span>/</span>
                  <span className="SequencerTopBarMetaCurrent">{formatClock(timelineDurationMs)}</span>
                  <span className="SequencerTopBarMetaStatus">{isMasterClient ? 'MASTER' : 'SLAVE'}</span>
                </div>
              </div>
            </div>
            <div className="SequencerTracksShell">
              <div
                className="SequencerTracksLabels"
                onWheel={(e) => {
                  const el = tracksScrollRef.current;
                  if (!el) return;
                  el.scrollLeft += e.deltaX;
                  el.scrollTop += e.deltaY;
                  scheduleUpdateTimelineScrollState();
                }}
              >
                <div className="SequencerTrackRow SequencerTagRow">
                  <div
                    className={`SequencerTrackLabel ${selectedTagId ? 'SequencerTrackLabelSelected' : ''}`}
                    onClick={() => {
                      setSelectedClipId(null);
                      setSelectedClipIds([]);
                      setSelectedTagId(null);
                      setEditingTagId(null);
                    }}
                  >
                    <div className="SequencerTrackControls" onClick={e => e.stopPropagation()}>
                      <button
                        className="SequencerSmallButton"
                        onClick={(e) => {
                          e.stopPropagation();
                          addTagAt(playheadRef.current);
                        }}
                        title={t('sequencer.addTag', 'Agregar tag')}
                        type="button"
                      >
                        ＋
                      </button>
                      <button
                        className="SequencerSmallButton"
                        onClick={(e) => {
                          e.stopPropagation();
                          autoTagFromLayer1();
                        }}
                        title="Autotag (Layer 1)"
                        type="button"
                      >
                        ✨
                      </button>
                      <button
                        className="SequencerSmallButton"
                        onClick={(e) => {
                          e.stopPropagation();
                          addTrack();
                        }}
                        title={t('sequencer.addLayer', 'Agregar layer')}
                        type="button"
                      >
                        + layer
                      </button>
                      <button
                        className={`SequencerSmallButton ${showTagsInOutput ? 'isOn' : ''}`}
                        onClick={(e) => {
                          e.stopPropagation();
                          setShowTagsInOutput(v => !v);
                        }}
                        title={showTagsInOutput ? 'TAGS: ON' : 'TAGS: OFF'}
                        type="button"
                      >
                        TAGS
                      </button>
                    </div>
                  </div>
                </div>

                <div className="SequencerTracksLabelsInner" style={{ transform: `translateY(${-timelineScrollTopPx}px)` }}>
                  {sequence.tracks.map((track, trackIndex) => {
                    const isSelectedTrack = track.id === selectedTrackId;
                    const isTrackActive = hasSoloTracks ? track.solo : !track.muted;
                    const isTrackInactive = !isTrackActive;
                    return (
                      <div key={track.id} className={`SequencerTrackRow ${isTrackInactive ? 'isInactive' : ''} ${track.collapsed ? 'isCollapsed' : ''}`}>
                        <div
                          className={`SequencerTrackLabel ${isSelectedTrack ? 'SequencerTrackLabelSelected' : ''}`}
                          onClick={() => setSelectedTrackId(track.id)}
                        >
                          <div className="SequencerTrackName">
                            <button
                              className="SequencerCollapseButton"
                              onClick={(e) => {
                                e.stopPropagation();
                                setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, collapsed: !t.collapsed } : t) }));
                              }}
                              title={track.collapsed ? 'Expand layer' : 'Collapse layer'}
                              type="button"
                            >
                              {track.collapsed ? '▸' : '▾'}
                            </button>
                            {track.collapsed ? (
                              <div className="SequencerTrackNameText">{track.name}</div>
                            ) : (
                              <input
                                value={track.name}
                                onChange={e => {
                                  const value = e.target.value;
                                  setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, name: value } : t) }));
                                }}
                              />
                            )}
                          </div>
                          <div className="SequencerTrackControls" onClick={e => e.stopPropagation()}>
                            {!track.collapsed && sequence.tracks.length > 1 && (
                              <>
                                <button
                                  className="SequencerSmallButton"
                                  disabled={trackIndex === 0}
                                  onClick={e => {
                                    e.stopPropagation();
                                    moveTrack(track.id, -1);
                                  }}
                                  title="Subir layer"
                                  type="button"
                                >
                                  ▲
                                </button>
                                <button
                                  className="SequencerSmallButton"
                                  disabled={trackIndex === sequence.tracks.length - 1}
                                  onClick={e => {
                                    e.stopPropagation();
                                    moveTrack(track.id, 1);
                                  }}
                                  title="Bajar layer"
                                  type="button"
                                >
                                  ▼
                                </button>
                              </>
                            )}
                            <button
                              className={`SequencerSmallButton ${track.muted ? 'isOn' : ''}`}
                              onClick={e => {
                                e.stopPropagation();
                                setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, muted: !t.muted } : t) }));
                              }}
                            >
                              M
                            </button>
                            <button
                              className={`SequencerSmallButton ${track.solo ? 'isOn' : ''}`}
                              onClick={e => {
                                e.stopPropagation();
                                setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === track.id ? { ...t, solo: !t.solo } : t) }));
                              }}
                            >
                              S
                            </button>
                            {!track.collapsed && sequence.tracks.length > 1 && (
                              <button
                                className="SequencerSmallButton"
                                onClick={e => {
                                  e.stopPropagation();
                                  removeTrack(track.id);
                                }}
                                title={t('common.delete', 'Eliminar')}
                              >
                                ×
                              </button>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div
                className="SequencerTracksScroll"
                ref={tracksScrollRef}
                onScroll={scheduleUpdateTimelineScrollState}
              >
                <div className="SequencerTrackRow SequencerTagRow">
                  <div
                    className="SequencerTrackLane SequencerTagLane"
                    style={{ width: effectiveLaneWidthPx }}
                    onDoubleClick={(e) => {
                      const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                      const x = e.clientX - rect.left;
                      const raw = laneXToTimeMs(x, pixelsPerSecondRef.current);
                      addTagAt(clamp(raw, 0, Math.max(0, timelineDurationMs)));
                    }}
                    onMouseDown={(e) => {
                      if (e.button !== 0) return;
                      const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                      const x = e.clientX - rect.left;
                      const next = clamp(laneXToTimeMs(x, pixelsPerSecondRef.current), 0, Math.max(0, timelineDurationMs));
                      setPlayhead(next);
                    }}
                  >
                    <div className="SequencerPlayhead" style={{ left: `${timeToLaneX(playheadMs, pixelsPerSecond)}px` }} />
                    {(() => {
                      const segs = getTagSegments(sequence);
                      return segs.map((seg, idx) => {
                        const tag = seg.tag;
                        const x = timeToLaneX(seg.startMs, pixelsPerSecond);
                        const width = Math.max(24, ((seg.endMs - seg.startMs) / 1000) * pixelsPerSecond);
                        const isSelected = selectedTagId === tag.id;
                        const isEditing = editingTagId === tag.id;
                        const isActive = playheadMs >= seg.startMs && playheadMs < seg.endMs;
                        const minStartMs = idx > 0 ? (segs[idx - 1]?.startMs ?? 0) + 1 : 0;
                        const maxEndMs = idx < segs.length - 1 ? (segs[idx + 1]?.startMs ?? seg.endMs) : Number.POSITIVE_INFINITY;
                        return (
                          <div
                            key={tag.id}
                            className={`SequencerTagSegment ${isSelected ? 'isSelected' : ''} ${isActive ? 'isActive' : ''}`}
                            style={{ left: `${x}px`, width: `${width}px` }}
                            onMouseDown={(e) => {
                              e.stopPropagation();
                              if (e.button !== 0) return;
                              setSelectedClipId(null);
                              setSelectedClipIds([]);
                              setSelectedTagId(tag.id);
                              setEditingTagId(null);
                              dragTagRef.current = { tagId: tag.id, startMs: tag.tMs, startX: e.clientX };
                              setIsDraggingTag(true);
                            }}
                            onDoubleClick={(e) => {
                              e.stopPropagation();
                              setSelectedClipId(null);
                              setSelectedClipIds([]);
                              setSelectedTagId(tag.id);
                              setEditingTagId(tag.id);
                            }}
                            title={tag.label || 'TAG'}
                          >
                            <div
                              className="SequencerTagResizeHandle SequencerTagResizeHandleStart"
                              onMouseDown={(e) => {
                                e.stopPropagation();
                                if (e.button !== 0) return;
                                setSelectedClipId(null);
                                setSelectedClipIds([]);
                                setSelectedTagId(tag.id);
                                setEditingTagId(null);
                                resizeTagRef.current = { tagId: tag.id, startMs: seg.startMs, endMs: seg.endMs, startX: e.clientX, edge: 'start', minStartMs, maxEndMs };
                                setIsResizingTag(true);
                              }}
                            />
                            <div className="SequencerTagDot" />
                            {isEditing ? (
                              <input
                                className="SequencerTagInput"
                                value={tag.label}
                                onChange={(e) => updateTagLabel(tag.id, e.target.value)}
                                onBlur={() => setEditingTagId(null)}
                                onKeyDown={(e) => {
                                  if (e.key === 'Enter' || e.key === 'Escape') {
                                    (e.currentTarget as HTMLInputElement).blur();
                                  }
                                }}
                                autoFocus
                              />
                            ) : (
                              <div className="SequencerTagText">{tag.label || 'TAG'}</div>
                            )}
                            <div
                              className="SequencerTagResizeHandle SequencerTagResizeHandleEnd"
                              onMouseDown={(e) => {
                                e.stopPropagation();
                                if (e.button !== 0) return;
                                setSelectedClipId(null);
                                setSelectedClipIds([]);
                                setSelectedTagId(tag.id);
                                setEditingTagId(null);
                                resizeTagRef.current = { tagId: tag.id, startMs: seg.startMs, endMs: seg.endMs, startX: e.clientX, edge: 'end', minStartMs, maxEndMs };
                                setIsResizingTag(true);
                              }}
                            />
                          </div>
                        );
                      });
                    })()}
                  </div>
                </div>
                {sequence.tracks.map((track) => {
                  const isTrackActive = hasSoloTracks ? track.solo : !track.muted;
                  const isTrackInactive = !isTrackActive;
                  const laneWidthPx2 = effectiveLaneWidthPx;
                  const playheadX = timeToLaneX(playheadMs, pixelsPerSecond);
                  return (
                    <div key={track.id} className={`SequencerTrackRow ${isTrackInactive ? 'isInactive' : ''} ${track.collapsed ? 'isCollapsed' : ''}`}>
                      <div
                        className="SequencerTrackLane"
                        style={{ width: laneWidthPx2 }}
                        ref={(el) => {
                          if (el) trackLaneRefs.current.set(track.id, el);
                          else trackLaneRefs.current.delete(track.id);
                        }}
                        onDragOver={(e) => {
                          e.preventDefault();
                          e.dataTransfer.dropEffect = 'copy';
                          setSelectedTrackId(track.id);
                        }}
                        onDrop={(e) => {
                          e.preventDefault();
                          const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                          const x = e.clientX - rect.left;
                          const startMs = Math.max(0, laneXToTimeMs(x, pixelsPerSecondRef.current));

                          setSelectedTrackId(track.id);

                          const layerId = e.dataTransfer.getData(LAYER_DND_MIME);
                          if (layerId) {
                            const layer = savedLayers.find(l => l.id === layerId);
                            if (layer) addLayerToTrack(layer, track.id, startMs);
                            return;
                          }

                          const presetId = e.dataTransfer.getData(PRESET_DND_MIME) || e.dataTransfer.getData(SEQUENCE_DND_MIME) || e.dataTransfer.getData('text/plain');
                          if (!presetId) return;
                          const presetAny = presetsById.get(presetId);
                          if (!presetAny) return;
                          addPresetOrSequenceClipToTrackAt(track.id, presetAny, startMs);
                        }}
                        onMouseDown={e => {
                          if (e.button !== 0) return;
                          const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                          const x = e.clientX - rect.left;
                          const clicked = clamp(laneXToTimeMs(x, pixelsPerSecondRef.current), 0, Math.max(0, timelineDurationMs));
                          setSelectedTrackId(track.id);
                          setSelectedClipId(null);
                          setSelectedClipIds([]);
                          setSelectedTagId(null);
                          setEditingTagId(null);

                          const clips = (track.clips || []).slice().sort((a, b) => a.startMs - b.startMs);
                          let prevEnd = 0;
                          for (const c of clips) {
                            const end = c.startMs + Math.max(1, c.durationMs);
                            if (end <= clicked && end >= prevEnd) prevEnd = end;
                          }
                          let nextStart: number | null = null;
                          for (const c of clips) {
                            if (c.startMs > clicked) {
                              nextStart = c.startMs;
                              break;
                            }
                          }
                          const nextPlayhead = nextStart != null && clicked > prevEnd && clicked < nextStart ? prevEnd : clicked;
                          setPlayheadImmediate(nextPlayhead);

                          scrubRef.current = {
                            trackId: track.id,
                            startX: e.clientX,
                            startTime: performance.now(),
                            rectLeft: rect.left,
                            started: false
                          };
                          setIsScrubbingTimeline(true);
                        }}
                      >
                        <div className="SequencerPlayhead" style={{ left: `${playheadX}px` }} />
                        {(() => {
                          const sortedClips = (track.clips || []).slice().sort((a, b) => a.startMs - b.startMs);
                          const vr = visibleTimelineRange;
                          const visibleClips = sortedClips.filter(clip => {
                            const clipEndMs = clip.startMs + Math.max(1, clip.durationMs);
                            return clipEndMs >= vr.startMs && clip.startMs <= vr.endMs;
                          });
                          return visibleClips.map((clip) => {
                            const left = Math.round(timeToLaneX(clip.startMs, pixelsPerSecond));
                            const width = Math.max(16, Math.round((clip.durationMs / 1000) * pixelsPerSecond));
                            const isSelected = selectedClipIdsSet.has(clip.id);
                            const presetName = clip.preset?.name || (clip.presetId ? presetsById.get(clip.presetId)?.name : '') || 'Clip';
                            const presetThumb = clip.preset && !isSequencePreset(clip.preset) ? getPresetThumbnailSrc(clip.preset) : undefined;
                            const kfDataForTimeline = (() => {
                              if (!clip.keyframes) return [];
                              const paramIds = Object.keys(clip.keyframes);
                              return paramIds.map(paramId => {
                                const frames = (clip.keyframes![paramId] || [])
                                  .filter((f: any) => f && typeof f.tMs === 'number' && isFinite(f.tMs) && typeof f.value === 'number' && isFinite(f.value))
                                  .slice()
                                  .sort((a: any, b: any) => a.tMs - b.tMs) as Array<{ tMs: number; value: number }>;
                                if (!frames.length) return null;
                                // Global param keyframes (global_ / compositeG_) store raw values (e.g. BPM=120)
                                // Shader param keyframes store normalized values (0.0-1.0)
                                const isGlobal = paramId.startsWith('global_') || paramId.startsWith('compositeG_');
                                const values = frames.map(f => f.value);
                                const minV = isGlobal ? Math.min(...values) : 0;
                                const maxV = isGlobal ? Math.max(...values) : 1;
                                const span = Math.max(1e-6, maxV - minV);
                                const color = paramLevelColors[paramId] || getKeyframeColorByIndex(paramIds.indexOf(paramId));
                                paramLevelColors[paramId] = color;
                                return { paramId, frames, minV, maxV, span, color };
                              }).filter(Boolean) as Array<{ paramId: string; frames: Array<{ tMs: number; value: number }>; minV: number; maxV: number; span: number; color: string }>;
                            })();
                            const hasAnyKF = kfDataForTimeline.some(d => d.frames.length > 0);
                            return (
                              <div
                                key={clip.id}
                                className={`SequencerClip ${isSelected ? 'SequencerClipSelected' : ''}`}
                                style={{ left, width }}
                                onMouseDown={e => {
                                  e.stopPropagation();
                                  if (e.button !== 0) return;
                                  setSelectedTagId(null);
                                  setEditingTagId(null);
                                  setSelectedTrackId(track.id);
                                  if (e.shiftKey || e.ctrlKey || e.metaKey) {
                                    setSelectedClipIds(prev => {
                                      const has = prev.includes(clip.id);
                                      const next = (e.ctrlKey || e.metaKey)
                                        ? (has ? prev.filter(id => id !== clip.id) : [...prev, clip.id])
                                        : (has ? prev : [...prev, clip.id]);
                                      const primary = next.length ? next[next.length - 1] : null;
                                      setSelectedClipId(primary);
                                      return next;
                                    });
                                  } else {
                                    setSelectedClipId(clip.id);
                                    setSelectedClipIds([clip.id]);
                                  }
                                  dragClipRef.current = { clipId: clip.id, startMs: clip.startMs, startX: e.clientX };
                                  setIsDraggingClip(true);
                                }}
                                title={presetName}
                              >
                                <div
                                  className="SequencerClipHandle SequencerClipHandleStart"
                                  onMouseDown={(e) => {
                                    e.stopPropagation();
                                    if (e.button !== 0) return;
                                    setSelectedClipId(clip.id);
                                    setSelectedClipIds([clip.id]);
                                    setSelectedTrackId(track.id);
                                    resizeClipRef.current = { trackId: track.id, clipId: clip.id, startMs: clip.startMs, durationMs: clip.durationMs, startX: e.clientX, edge: 'start' };
                                    setIsResizingClip(true);
                                  }}
                                />
                                {presetThumb && !track.collapsed && <img className="SequencerClipThumb" src={presetThumb} alt="" draggable={false} />}
                                {presetName}
                                {hasAnyKF && (
                                  <div className="SequencerClipKeyframes">
                                    {kfDataForTimeline.map(kfData => (
                                      <svg key={kfData.paramId} className="SequencerClipKeyframesSvg" viewBox="0 0 1000 1000" preserveAspectRatio="none">
                                        {kfData.frames.length >= 2 && (
                                          <path
                                            d={kfData.frames.map((f, idx) => {
                                              const x = (clamp(f.tMs, 0, clip.durationMs) / Math.max(1, clip.durationMs)) * 1000;
                                              const y = 1000 - ((f.value - kfData.minV) / kfData.span) * 1000;
                                              return `${idx === 0 ? 'M' : 'L'} ${x.toFixed(2)} ${clamp(y, 0, 1000).toFixed(2)}`;
                                            }).join(' ')}
                                            fill="none"
                                            stroke={kfData.color}
                                            strokeWidth="20"
                                            strokeLinecap="round"
                                            strokeLinejoin="round"
                                          />
                                        )}
                                      </svg>
                                    ))}
                                    {kfDataForTimeline.map(kfData =>
                                      kfData.frames.map((f) => {
                                        const tLocal = clamp(f.tMs, 0, clip.durationMs);
                                        const xPct = (tLocal / Math.max(1, clip.durationMs)) * 100;
                                        const yPct = (1 - ((f.value - kfData.minV) / kfData.span)) * 100;
                                        const isActive = selectedKeyframeTMs != null && Math.abs(selectedKeyframeTMs - tLocal) <= 6;
                                        return (
                                          <div
                                            key={`${kfData.paramId}:${f.tMs}`}
                                            className={`SequencerClipKeyframe ${isActive ? 'isActive' : ''}`}
                                            style={{
                                              left: `${clamp(xPct, 0, 100)}%`,
                                              top: `${clamp(yPct, 0, 100)}%`,
                                              borderColor: isActive ? 'rgba(255,255,255,0.95)' : kfData.color,
                                              background: kfData.color,
                                              opacity: 0.85
                                            }}
                                            title={`${kfData.paramId} @ ${formatClock(tLocal)}\n${f.value.toFixed(3)}`}
                                            onPointerDown={(e) => {
                                              e.stopPropagation();
                                              if (e.button !== 0) return;
                                              setSelectedClipId(clip.id);
                                              setSelectedClipIds([clip.id]);
                                              setSelectedTrackId(track.id);
                                              setSelectedKeyframeTMs(tLocal);
                                              setPlayhead(clip.startMs + tLocal);
                                              const dotEl = e.currentTarget as HTMLElement;
                                              const clipRect = dotEl.closest('.SequencerClip')?.getBoundingClientRect();
                                              if (!clipRect) return;
                                              const kfSpan = kfData.span;
                                              const kfMinV = kfData.minV;
                                              const doc = e.currentTarget.ownerDocument;
                                              const onMove = (ev: PointerEvent) => {
                                                ev.preventDefault();
                                                const relX = ev.clientX - clipRect.left;
                                                const newTMs = (relX / Math.max(1, clipRect.width)) * clip.durationMs;
                                                const clampedTMs = clamp(newTMs, 0, clip.durationMs);
                                                const relY = ev.clientY - clipRect.top;
                                                const newNormY = 1 - (relY / Math.max(1, clipRect.height));
                                                const newValue = kfMinV + newNormY * kfSpan;
                                                const clampedValue = clamp(newValue, kfMinV, kfMinV + kfSpan);
                                                moveKeyframeForSelectedClip(kfData.paramId, tLocal, clampedTMs, clampedValue);
                                                setSelectedKeyframeTMs(clampedTMs);
                                                setPlayhead(clip.startMs + clampedTMs);
                                              };
                                              const onUp = () => {
                                                doc.removeEventListener('pointermove', onMove);
                                                doc.removeEventListener('pointerup', onUp);
                                              };
                                              doc.addEventListener('pointermove', onMove);
                                              doc.addEventListener('pointerup', onUp);
                                            }}
                                          />
                                        );
                                      })
                                    )}
                                  </div>
                                )}
                                <div
                                  className="SequencerClipHandle SequencerClipHandleEnd"
                                  onMouseDown={(e) => {
                                    e.stopPropagation();
                                    if (e.button !== 0) return;
                                    setSelectedClipId(clip.id);
                                    setSelectedClipIds([clip.id]);
                                    setSelectedTrackId(track.id);
                                    resizeClipRef.current = { trackId: track.id, clipId: clip.id, startMs: clip.startMs, durationMs: clip.durationMs, startX: e.clientX, edge: 'end' };
                                    setIsResizingClip(true);
                                  }}
                                />
                              </div>
                            );
                          });
                        })()}
                      </div>
                    </div>
                  );
                })}
              </div>
