                <div
                  className="SequencerTimeBarTrack"
                  onDragOver={(e) => {
                    const hasPreset = e.dataTransfer.types.includes(PRESET_DND_MIME) || e.dataTransfer.types.includes(SEQUENCE_DND_MIME) || e.dataTransfer.types.includes('text/plain');
                    const hasLayer = e.dataTransfer.types.includes(LAYER_DND_MIME);
                    if (!hasPreset && !hasLayer) return;
                    e.preventDefault();
                    e.dataTransfer.dropEffect = 'copy';
                  }}
                  onDrop={(e) => {
                    e.preventDefault();
                    const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                    const x = e.clientX - rect.left;
                    const raw = laneXToTimeMs(Math.max(0, x) + timelineScrollLeftPx, pixelsPerSecondRef.current);
                    const startMs = Math.max(0, raw);

                    const trackId = sequence.tracks.find(t => t.id === selectedTrackId)?.id || sequence.tracks[0]?.id;
                    if (!trackId) return;
                    setSelectedTrackId(trackId);

                    const layerId = e.dataTransfer.getData(LAYER_DND_MIME);
                    if (layerId) {
                      const layer = savedLayers.find(l => l.id === layerId);
                      if (layer) addLayerToTrack(layer, trackId, startMs);
                      return;
                    }

                    const presetId = e.dataTransfer.getData(PRESET_DND_MIME) || e.dataTransfer.getData(SEQUENCE_DND_MIME) || e.dataTransfer.getData('text/plain');
                    if (!presetId) return;
                    const presetAny = presetsById.get(presetId);
                    if (!presetAny) return;
                    addPresetOrSequenceClipToTrackAt(trackId, presetAny, startMs);
                  }}
                >
                  <div
                    className="SequencerTimeBarViewport"
                    onMouseDown={(e) => {
                      if (e.button !== 0) return;
                      const rect = (e.currentTarget as HTMLDivElement).getBoundingClientRect();
                      const x = e.clientX - rect.left;
                      const tMs = laneXToTimeMs(Math.max(0, x) + timelineScrollLeftPx, pixelsPerSecondRef.current);
                      const next = clamp(tMs, 0, Math.max(0, timelineDurationMs));
                      setPlayhead(next);

                      // Enable drag-to-scrub on timebar (reuses existing scrubRef infrastructure)
                      scrubRef.current = {
                        trackId: '',
                        startX: e.clientX,
                        startTime: performance.now(),
                        rectLeft: rect.left,
                        started: false
                      };
                      setIsScrubbingTimeline(true);
                    }}
                  >
                    <div ref={playheadDotRef} className="SequencerTimeBarPlayhead" style={{ left: `${timeToLaneX(playheadMs, pixelsPerSecond) - timelineScrollLeftPx}px` }} />
                    <div
                      className="SequencerTimeBarContent"
                      style={{ width: effectiveLaneWidthPx, transform: `translateX(${-timelineScrollLeftPx}px)` }}
