                      {rulerMarks.filter(m => {
                        return m.xPx >= visibleTimelineRange.startPx && m.xPx <= visibleTimelineRange.endPx;
                      }).map(m => (
                        <div key={m.tMs} className={`SequencerRulerTick ${m.isMajor ? 'isMajor' : 'isMinor'}`} style={{ left: `${m.xPx}px` }}>
                          <div className="SequencerRulerLine" />
                          {m.label ? <div className="SequencerRulerText">{m.label}</div> : null}
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <OutputCanvasDisplay
            ref={outputCanvasRef}
            visible={showOutputMap}
            outputPreset={outputPreset}
            onOutputPresetChange={setOutputPreset}
            isMinimized={isOutputMinimized}
            broadcastUpdate={broadcastUpdate as any}
            showConfigButton={false}
            openConfigSignal={outputConfigOpenSignal}
          />
        </div>

        {isMobileLayout && !isMobileInspectorOpen ? (
          <button
            className="SequencerMobileInspectorToggle"
