                              <input
                                type="number"
                                min={0}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorFrequency ?? 1.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorFrequency', Number(e.target.value))}
                                className="slider-value-number"
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Color Speed</label>
                              <input
                                type="range"
                                min={-10}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorSpeed ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorSpeed', Number(e.target.value))}
                                style={{ flex: 1 }}
                              />
                              <input
                                type="number"
                                min={-10}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorSpeed ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorSpeed', Number(e.target.value))}
                                className="slider-value-number"
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Color Offset</label>
                              <input
                                type="range"
                                min={0}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorOffset ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorOffset', Number(e.target.value))}
                                style={{ flex: 1 }}
                              />
                              <input
                                type="number"
                                min={0}
                                max={10}
                                step={0.01}
                                value={track?.colorSettings?.colorOffset ?? 0.0}
                                onChange={(e) => setSelectedTrackColorSetting('colorOffset', Number(e.target.value))}
                                className="slider-value-number"
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Flip X</label>
                              <input
                                type="checkbox"
                                checked={!!track?.colorSettings?.colorFlipX}
                                onChange={(e) => setSelectedTrackColorSetting('colorFlipX', e.target.checked)}
                              />
                            </div>

                            <div className="SequencerFieldRow">
                              <label>Flip Y</label>
                              <input
                                type="checkbox"
                                checked={!!track?.colorSettings?.colorFlipY}
                                onChange={(e) => setSelectedTrackColorSetting('colorFlipY', e.target.checked)}
                              />
                            </div>
                          </>
                        ) : (
                          <div style={{ fontSize: 12, opacity: 0.7 }}>
                            Activá LAYER COLORS para elegir colores del layer.
                          </div>
                        )}
                      </>
                    );
                  })()}

                  <div className="SequencerFieldRow">
                    <label>{t('sequencer.layerName', 'Layer')}</label>
                    <input
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.name ?? ''}
                      onChange={(e) => {
                        const value = e.target.value;
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, name: value } : t) }));
                      }}
                    />
                  </div>
                  <div className="SequencerFieldRow">
                    <label>{t('sequencer.brightness', 'Brillo')}</label>
                    <input
                      type="range"
                      min={0}
                      max={2}
                      step={0.01}
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.brightness ?? 1}
                      onChange={e => {
                        const value = Number(e.target.value);
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, brightness: value } : t) }));
                      }}
                      style={{ flex: 1 }}
                    />
                    <input
                      type="number"
                      min={0}
                      max={2}
                      step={0.01}
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.brightness ?? 1}
                      onChange={e => {
                        const value = Number(e.target.value);
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, brightness: value } : t) }));
                      }}
                      className="slider-value-number"
                    />
                  </div>
                  <div className="SequencerFieldRow">
                    <label>{t('sequencer.blend', 'Blend')}</label>
                    <select
                      value={sequence.tracks.find(t => t.id === selectedTrackId)?.blendMode ?? 1}
                      onChange={(e) => {
                        const value = Number(e.target.value);
                        setSequence(prev => ({ ...prev, tracks: prev.tracks.map(t => t.id === selectedTrackId ? { ...t, blendMode: value } : t) }));
                      }}
                    >
                      {BLEND_MODE_OPTIONS.map(opt => (
                        <option key={opt.value} value={opt.value}>{opt.label}</option>
                      ))}
                    </select>
                  </div>

                  {selected && (
                    <>
                      <div className="SequencerFieldRow">
                        <label>{t('sequencer.start', 'Inicio')}</label>
                        <input
                          type="number"
                          value={selected.clip.startMs}
                          onChange={e => {
                            const value = Number(e.target.value);
                            setSequence(prev => ({
                              ...prev,
                              tracks: prev.tracks.map(t => t.id !== selected.track.id ? t : ({
                                ...t,
                                clips: sortTrackOnly({
                                  ...t,
                                  clips: t.clips.map(c => c.id !== selected.clip.id ? c : ({ ...c, startMs: Math.max(0, value) }))
                                }).clips
                              }))
                            }));
                          }}
                        />
                      </div>

                      <div className="SequencerFieldRow">
                        <label>{selectedClipIds.length > 1 ? `${t('sequencer.duration', 'Duración')} (x${selectedClipIds.length})` : t('sequencer.duration', 'Duración')}</label>
                        <input
                          type="text"
                          value={durationTextClipId === selected.clip.id ? durationText : formatClockMs(selected.clip.durationMs)}
                          onChange={e => {
                            setDurationText(e.target.value);
                            setDurationTextClipId(selected.clip.id);
                          }}
                          onBlur={() => {
                            const parsed = parseTimecodeToMs(durationText);
                            if (parsed == null) {
                              setDurationText(formatClockMs(selected.clip.durationMs));
                              setDurationTextClipId(selected.clip.id);
                              return;
                            }
                            const value = Math.max(1, parsed);
                            const ids = selectedClipIds.length ? selectedClipIds : [selected.clip.id];
                            const idsSet = new Set(ids);
                            setSequence(prev => ({
                              ...prev,
                              tracks: prev.tracks.map(t => {
                                if (!(t.clips || []).some(c => idsSet.has(c.id))) return t;
                                return {
                                  ...t,
                                  clips: sortTrackOnly({
                                    ...t,
                                    clips: t.clips.map(c => idsSet.has(c.id) ? ({ ...c, durationMs: value }) : c)
                                  }).clips
                                };
                              })
                            }));
                            setDurationText(formatClockMs(value));
                            setDurationTextClipId(selected.clip.id);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') {
                              (e.currentTarget as HTMLInputElement).blur();
                              return;
                            }
                            if (e.key === 'Escape') {
                              setDurationText(formatClockMs(selected.clip.durationMs));
                              setDurationTextClipId(selected.clip.id);
                              (e.currentTarget as HTMLInputElement).blur();
                            }
                          }}
                        />
                      </div>

                      <div className="SequencerFieldRow" style={{ gap: 6 }}>
                        <button className="SequencerSmallButton" onClick={() => setPlayhead(selected.clip.startMs)} type="button">
                          {t('sequencer.goStart', 'Ir al inicio')}
                        </button>
                        <button className="SequencerSmallButton" onClick={() => setPlayhead(selected.clip.startMs + selected.clip.durationMs)} type="button">
                          {t('sequencer.goEnd', 'Ir al final')}
                        </button>
                        <button className="SequencerSmallButton" onClick={removeSelectedClip} type="button">
                          {t('common.delete', 'Eliminar')}
                        </button>
                      </div>
                    </>
                  )}
                </div>
              )}

              {inspectorTab === 'params' && (
                <div className="SequencerInspectorSectionBody">
